'use strict';
let state=0; const probes=[];
function* subject(){
yield 0;
try{yield state;
if(false){
try{
if(false){
print('observe-0:'+state);
}else{state=(state+(0))|0;print('else:'+state);}
}finally{print('finally');
print('observe-1:'+state);
}
}else{state=(state+(0))|0;print('else:'+state);}
return state;
}finally{print('request-finally');const received=yield state;print('request-finally-resume:'+received);}
}
function finish(value){print('result:'+value); for(let p=0;p<probes.length;++p){print('capture:'+probes[p]());} print('state:'+state);}
function failed(error){print('throw:'+error);finish(undefined);}
function drive(){
const iterator=subject(); let ordinal=0; let step=iterator.next();
print('step:'+step.done+':'+step.value); while(!step.done){
if(ordinal===1){++ordinal;step=iterator.return(7);}else{step=iterator.next(++ordinal);}
print('step:'+step.done+':'+step.value);}
finish(step.value);}
try{drive();}catch(error){failed(error);}
void 0;
